package com.complaintbox.service;
import com.complaintbox.dto.AuthDtos.*; import com.complaintbox.entity.*; import com.complaintbox.exception.ApiException; import com.complaintbox.repository.*; import jakarta.servlet.http.HttpSession; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AuthService { private final ResidentRepository residents; private final StaffRepository staff; private final PasswordEncoder encoder; public AuthService(ResidentRepository r,StaffRepository s,PasswordEncoder e){residents=r;staff=s;encoder=e;}
 public Map<String,Object> login(Login in,HttpSession session){ if("warden".equalsIgnoreCase(in.role())||"staff".equalsIgnoreCase(in.role())){Staff x=staff.findByEmail(in.email().trim().toLowerCase()).orElseThrow(()->new ApiException("Email, password, or role is incorrect.")); if(!encoder.matches(in.password(),x.getPassword())) throw new ApiException("Email, password, or role is incorrect."); session.setAttribute("STAFF_ID",x.getId());session.setAttribute("ROLE",x.getRole().name());return staffMap(x);} Resident r=residents.findByEmail(in.email().trim().toLowerCase()).orElseThrow(()->new ApiException("Email, password, or role is incorrect.")); if(!encoder.matches(in.password(),r.getPassword())) throw new ApiException("Email, password, or role is incorrect.");session.setAttribute("RESIDENT_ID",r.getId());session.setAttribute("ROLE","STUDENT");return residentMap(r); }
 public Map<String,Object> register(Register in,HttpSession s){if(in.password()==null||!in.password().equals(in.confirmPassword())) throw new ApiException("Passwords do not match."); if(residents.findByEmail(in.email().trim().toLowerCase()).isPresent()) throw new ApiException("An account already exists for this email."); Resident r=new Resident(in.name().trim(),in.email().trim().toLowerCase(),encoder.encode(in.password()),in.studentId()!=null?in.studentId():in.residentId(),in.roomNumber(),in.hostelBlock()); residents.save(r);s.setAttribute("RESIDENT_ID",r.getId());s.setAttribute("ROLE","STUDENT");return residentMap(r);}
 public Object me(HttpSession s){Object role=s.getAttribute("ROLE");if("STUDENT".equals(role)){Long id=(Long)s.getAttribute("RESIDENT_ID");return residents.findById(id).map(this::residentMap).orElse(null);} if(role!=null){Long id=(Long)s.getAttribute("STAFF_ID");return staff.findById(id).map(this::staffMap).orElse(null);}return null;}
 public void logout(HttpSession s){s.invalidate();} public Long residentId(HttpSession s){if(!"STUDENT".equals(s.getAttribute("ROLE")))throw new ApiException("Student login required");return (Long)s.getAttribute("RESIDENT_ID");} public Long staffId(HttpSession s){if(!"WARDEN".equals(s.getAttribute("ROLE"))&&!"MAINTENANCE".equals(s.getAttribute("ROLE")))throw new ApiException("Staff login required");return (Long)s.getAttribute("STAFF_ID");}
 private Map<String,Object> residentMap(Resident r){Map<String,Object> m=new LinkedHashMap<>();m.put("id",r.getId());m.put("name",r.getName());m.put("email",r.getEmail());m.put("studentId",r.getResidentId());m.put("roomNumber",r.getRoomNumber());m.put("hostelBlock",r.getHostelBlock());m.put("phone",r.getPhone());m.put("role","user");m.put("createdAt",null);return m;} private Map<String,Object> staffMap(Staff x){Map<String,Object> m=new LinkedHashMap<>();m.put("id",x.getId());m.put("name",x.getName());m.put("email",x.getEmail());m.put("specialty",x.getSpecialty());m.put("phone",x.getPhone());m.put("role",x.getRole()==StaffRole.WARDEN?"admin":"staff");return m;}
}
